<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Playful Billiards</title>
<style>
  body{margin:0;background:#006400;display:flex;justify-content:center;align-items:center;height:100vh;font-family:sans-serif;}
  canvas{background:#004d00;border-radius:5px;}
  #controls{position:absolute;top:10px;left:10px;color:white;pointer-events:none;}
  button{padding:.3em .6em;background:#222;color:white;border:none;border-radius:4px;margin-right:.5em;cursor:pointer;}
  #instructions{background:rgba(0,0,0,.6);padding:.5em 1em;border-radius:4px;font-size:.9rem;}
</style>
</head>
<body>
<canvas id="table"></canvas>
<div id="controls">
  <button id="resetBtn">Reset / Rack</button>
  <div id="instructions">Click & drag the white ball to aim. Release to shoot.</div>
</div>
<script>
(() => {
  const canvas = document.getElementById('table');
  const ctx = canvas.getContext('2d');

  // Playfield constants
  const W = 800; // width in pixels
  const H = 400; // height in pixels
  const R = 10;  // ball radius
  const pocketRadius = 18;
  const pockets = [
    {x:0, y:0}, {x:W/2, y:0}, {x:W, y:0},
    {x:0, y:H}, {x:W/2, y:H}, {x:W, y:H}
  ];
  canvas.width = W;
  canvas.height = H;

  // Physics constants
  const friction = 200; // pixels per second^2
  const dtMax = 1/30;   // max time step for stability

  let balls = [];       // current ball state array
  let animId = null;
  let lastTime = null;
  let paused = false;

  // Mouse interaction
  let dragging = false;
  let dragStart = {x:0,y:0};
  let cueBallIdx = -1;
  const maxSpeed = 800; // pixels per second

  function draw() {
    // table background
    ctx.fillStyle='#004d00';
    ctx.fillRect(0,0,W,H);
    // pockets
    ctx.fillStyle='black';
    for(const p of pockets){
      ctx.beginPath();ctx.arc(p.x,p.y,pocketRadius,0,Math.PI*2);ctx.fill();
    }
    // balls
    for(let i=0;i<balls.length;i++){
      const b = balls[i];
      if(b.potted) continue;
      ctx.beginPath();
      ctx.arc(b.x,b.y,R,0,Math.PI*2);
      ctx.fillStyle=b.cue?'white':'red';
      ctx.fill();
      ctx.strokeStyle='black';ctx.lineWidth=1;ctx.stroke();
    }
  }

  function step(dt){
    // clamp dt
    while(dt>dtMax){step(dtMax);dt-=dtMax;return;}
    // update positions
    for(const b of balls){
      if(b.potted) continue;
      b.x+=b.vx*dt;
      b.y+=b.vy*dt;
      // friction deceleration
      const speed=Math.hypot(b.vx,b.vy);
      if(speed>0){
        const dec=friction*dt;
        const newSpeed=Math.max(0,speed-dec);
        if(newSpeed===0){b.vx=b.vy=0;}
        else{const scale=newSpeed/speed;b.vx*=scale;b.vy*=scale;}
      }
    }
    // wall collisions
    for(const b of balls){
      if(b.potted) continue;
      if(b.x-R<0){b.x=R; b.vx=-b.vx;}
      if(b.x+R>W){b.x=W-R; b.vx=-b.vx;}
      if(b.y-R<0){b.y=R; b.vy=-b.vy;}
      if(b.y+R>H){b.y=H-R; b.vy=-b.vy;}
    }
    // ball-ball collisions
    for(let i=0;i<balls.length;i++){
      const a=balls[i];
      if(a.potted) continue;
      for(let j=i+1;j<balls.length;j++){
        const b=balls[j];
        if(b.potted) continue;
        const dx=b.x-a.x, dy=b.y-a.y;
        const dist=Math.hypot(dx,dy);
        if(dist<R*2){
          // resolve overlap
          const overlap=(R*2-dist)/2;
          a.x-=dx/Math.max(1e-6,dist)*overlap;
          a.y-=dy/Math.max(1e-6,dist)*overlap;
          b.x+=dx/Math.max(1e-6,dist)*overlap;
          b.y+=dy/Math.max(1e-6,dist)*overlap;
          // elastic collision
          const nx=dx/dist, ny=dy/dist;
          const p=(2*(a.vx*nx+a.vy*ny - b.vx*nx-b.vy*ny))/(2);
          a.vx-=p*nx; a.vy-=p*ny;
          b.vx+=p*nx; b.vy+=p*ny;
        }
      }
    }
    // pockets
    for(const b of balls){
      if(b.potted) continue;
      for(const p of pockets){
        const dx=b.x-p.x, dy=b.y-p.y;
        if(Math.hypot(dx,dy)<pocketRadius){
          b.potted=true; b.vx=b.vy=0; break;
        }
      }
    }

    draw();
  }

  function animate(now){
    if(paused){lastTime=now; animId=requestAnimationFrame(animate);return;}
    const dt=(now-lastTime)/1000;
    step(dt);
    lastTime=now;
    animId=requestAnimationFrame(animate);
  }

  // Public API
  window.sim={
    W,W,H,R,
    reset: (initBalls)=>{
      balls=initBalls.map(b=>{
        return {x:b.x,y:b.y,vx:b.vx||0,vy:b.vy||0,potted:false,cue:!!b.cue};
      });
      // find cue ball index
      cueBallIdx=balls.findIndex(b=>b.cue);
    },
    step(dt){step(dt);},
    state(){return balls.map(b=>({...b}));},
    shoot(vx,vy){
      if(cueBallIdx<0) return;
      const b=balls[cueBallIdx];
      if(b.potted) return;
      b.vx=vx; b.vy=vy;
    },
    pause(){paused=true;},
    resume(){paused=false;}
  };

  // UI
  document.getElementById('resetBtn').addEventListener('click',()=>{
    const rack=[
      {x:W/2,y:H/2+R*3, cue:true},
      {x:W/2-1.5*R,y:H/2+R*2},{x:W/2+1.5*R,y:H/2+R*2},
      {x:W/2-3*R,y:H/2+R},{x:W/2+3*R,y:H/2+R},
      {x:W/2-4.5*R,y:H/2},{x:W/2+4.5*R,y:H/2}
    ];
    window.sim.reset(rack);
  });
  document.getElementById('resetBtn').click(); // initial rack

  canvas.addEventListener('mousedown',e=>{
    if(paused) return;
    const rect=canvas.getBoundingClientRect();
    const mx=e.clientX-rect.left, my=e.clientY-rect.top;
    if(cueBallIdx<0) return;
    const b=balls[cueBallIdx];
    if(b.potted) return;
    if(Math.hypot(mx-b.x,my-b.y)<=R){
      dragging=true; dragStart={x:mx,y:my};
    }
  });
  canvas.addEventListener('mousemove',e=>{
    if(!dragging) return;
    const rect=canvas.getBoundingClientRect();
    const mx=e.clientX-rect.left, my=e.clientY-rect.top;
    const b=balls[cueBallIdx];
    // draw aim line
    draw();
    ctx.strokeStyle='yellow';
    ctx.lineWidth=2;
    ctx.beginPath();ctx.moveTo(b.x,b.y);ctx.lineTo(mx,my);ctx.stroke();
  });
  canvas.addEventListener('mouseup',e=>{
    if(!dragging) return;
    dragging=false;
    const rect=canvas.getBoundingClientRect();
    const mx=e.clientX-rect.left, my=e.clientY-rect.top;
    const b=balls[cueBallIdx];
    const dx=b.x-mx, dy=b.y-my; // direction from drag end to ball
    let speed=Math.hypot(dx,dy);
    if(speed>maxSpeed) speed=maxSpeed;
    const norm= Math.max(1e-6,speed);
    b.vx = (dx/norm)*speed;
    b.vy = (dy/norm)*speed;
  });

  // Start animation
  lastTime=performance.now();
  animId=requestAnimationFrame(animate);
})();
</script>
</body>
</html>
